# Shapes for the quantized LSTM cell: (batch_size, input_size, hidden_size).
LSTM_CELL_SHAPES = [
    (1, 4, 4),
    (2, 8, 6),
    (4, 16, 12),
    (8, 32, 16),
    (16, 64, 32),
    (32, 128, 64),
]


def _choose_qparams_u8(t):
    """FBGEMM ChooseQuantizationParams(min, max, 0, 255) on the host."""
    v_min = min(t.min().item(), 0.0)
    v_max = max(t.max().item(), 0.0)
    scale = float((v_max - v_min) / 255.0)
    if scale == 0.0 or 1.0 / scale == float("inf"):
        scale = 0.1
    if scale < 6.1e-5:
        scale = 6.1e-5
    zp_from_min = 0.0 - v_min / scale
    zp_from_max = 255.0 - v_max / scale
    err_from_min = 0.0 + abs(v_min / scale)
    err_from_max = 255.0 + abs(v_max / scale)
    initial = zp_from_min if err_from_min < err_from_max else zp_from_max
    if initial < 0.0:
        return scale, 0
    if initial > 255.0:
        return scale, 255
    return scale, int(round(initial))


def _quantized_linear(x, qw, col_offsets, w_scale, w_zp, bias):
    """fbgemm_linear_int8_weight_fp32_activation with device ops.

    Dynamically quantizes the activation to uint8 from its own min/max,
    accumulates int8 x int8 in integer arithmetic, applies the FBGEMM
    col_offsets / row-sum / zero-point corrections and dequantizes with
    (a_scale * w_scale). The centred activation (xq - 128) and the weight are
    integer-valued, so the device matmul carries the same integers the FBGEMM
    kernel would, which keeps the baseline a measurement of the quantized
    contract rather than of an fp32 LSTM.
    """
    a_scale, a_zp = _choose_qparams_u8(x)
    xq = torch.round(x * (1.0 / a_scale) + a_zp).clamp_(0, 255)
    X = (xq - 128).to(torch.float32)
    W = qw.to(torch.float32)
    raw = (
        X @ W.t()
        + float(128 - a_zp) * col_offsets.to(torch.float32)
        - float(w_zp) * X.sum(1, keepdim=True)
    )
    return raw * (a_scale * w_scale) + bias


def _torch_quantized_lstm_cell(
    input,
    hx,
    w_ih,
    w_hh,
    b_ih,
    b_hh,
    packed_ih,
    packed_hh,
    col_offsets_ih,
    col_offsets_hh,
    scale_ih,
    scale_hh,
    zero_point_ih,
    zero_point_hh,
):
    """Torch baseline: the native FBGEMM int8 cell arithmetic on device.

    aten::quantized_lstm_cell itself has no CUDA kernel (QuantizedCellParams
    only implements the FBGEMM CPU path and its CUDA dispatch raises
    "matmul is not supported"), so the baseline expresses the identical FBGEMM
    integer contract with device ops: dynamic uint8 quantization of both
    activations, integer accumulation of the int8 operands with the
    col_offsets / row-sum / zero-point corrections, and dequantization with
    the weight scales. Both sides consume the same int8 weights, column
    offsets, scales and zero points.
    """
    h_state, c_state = hx
    x_gates = _quantized_linear(
        input, w_ih, col_offsets_ih, scale_ih, zero_point_ih, b_ih
    )
    h_gates = _quantized_linear(
        h_state, w_hh, col_offsets_hh, scale_hh, zero_point_hh, b_hh
    )
    gates = h_gates + x_gates
    i, f, g, o = gates.chunk(4, dim=-1)
    i = torch.sigmoid(i)
    f = torch.sigmoid(f)
    g = torch.tanh(g)
    o = torch.sigmoid(o)
    cy = f * c_state + i * g
    hy = o * torch.tanh(cy)
    return hy, cy


class QuantizedLstmCellBenchmark(base.Benchmark):
    def set_shapes(self, shape_file_path=None):
        self.shapes = LSTM_CELL_SHAPES

    def get_input_iter(self, cur_dtype):
        torch.backends.quantized.engine = "fbgemm"
        for shape in self.shapes:
            batch_size, input_size, hidden_size = shape
            input = torch.randn(
                batch_size, input_size, dtype=torch.float32, device=self.device
            )
            h0 = torch.randn(
                batch_size, hidden_size, dtype=torch.float32, device=self.device
            )
            c0 = torch.randn(
                batch_size, hidden_size, dtype=torch.float32, device=self.device
            )
            b_ih = torch.randn(4 * hidden_size, dtype=torch.float32, device=self.device)
            b_hh = torch.randn(4 * hidden_size, dtype=torch.float32, device=self.device)
            (
                qw_ih,
                qw_hh,
                co_ih,
                co_hh,
                s_ih,
                s_hh,
                zp_ih,
                zp_hh,
                packed_ih,
                packed_hh,
            ) = _make_quantization(input_size, hidden_size)
            yield (
                input,
                (h0, c0),
                qw_ih,
                qw_hh,
                b_ih,
                b_hh,
                packed_ih,
                packed_hh,
                co_ih,
                co_hh,
                s_ih,
                s_hh,
                zp_ih,
                zp_hh,
            )


def _make_quantization(input_size, hidden_size):
    """Quantize random float weights exactly like the FBGEMM path.

    Returns the int8 weights, column offsets, scales, zero points and the
    packed FBGEMM handles, all self-consistent for one dynamic-quantized cell.
    """
    w_ih = torch.randn(4 * hidden_size, input_size)
    w_hh = torch.randn(4 * hidden_size, hidden_size)
    qw_ih, col_offsets_ih, scale_ih, zero_point_ih = (
        torch.ops.aten.fbgemm_linear_quantize_weight(w_ih)
    )
    qw_hh, col_offsets_hh, scale_hh, zero_point_hh = (
        torch.ops.aten.fbgemm_linear_quantize_weight(w_hh)
    )
    packed_ih = torch.ops.aten.fbgemm_pack_quantized_matrix(qw_ih)
    packed_hh = torch.ops.aten.fbgemm_pack_quantized_matrix(qw_hh)
    return (
        qw_ih.cuda(),
        qw_hh.cuda(),
        col_offsets_ih.cuda(),
        col_offsets_hh.cuda(),
        float(scale_ih),
        float(scale_hh),
        int(zero_point_ih),
        int(zero_point_hh),
        packed_ih,
        packed_hh,
    )


